mapper.select:
SELECT room_id
FROM dm_rooms
WHERE pair_key = #{pairKey}

mapper.insert:
INSERT INTO dm_rooms (
    room_type, title, created_by, pair_key, created_at
) VALUES (
    #{roomType}, #{title}, #{createdBy}, #{pairKey}, NOW()
)

mapper.update:
UPDATE dm_members
SET last_read_message_id = #{messageId}
WHERE room_id = #{roomId}
  AND user_id = #{userId}
  AND left_at IS NULL
  AND (last_read_message_id IS NULL OR last_read_message_id < #{messageId})

mapper.select:
SELECT m.room_id AS roomId, u.user_id AS userId, u.nickname AS nickname, u.profile_image_url AS profileImageUrl, m.last_read_message_id AS lastReadMessageId FROM dm_members m JOIN users u ON u.user_id = m.user_id WHERE m.user_id <> #{userId} AND m.left_at IS NULL AND m.room_id IN
#{roomId}
ORDER BY m.room_id, u.user_id

SELECT EXISTS (
    SELECT 1
    FROM dm_members
    WHERE room_id = #{roomId}
      AND user_id = #{userId}
      AND left_at IS NULL
)
